package store.adityastudio.deliverymanage;
import android.app.*;import android.content.Intent;import android.os.Build;import androidx.annotation.NonNull;import androidx.core.app.NotificationCompat;import com.capacitorjs.plugins.pushnotifications.PushNotificationsPlugin;import com.google.firebase.messaging.FirebaseMessagingService;import com.google.firebase.messaging.RemoteMessage;
public class DeliveryMessagingService extends FirebaseMessagingService {public static final String CHANNEL_ID="delivery_fullscreen_v3";@Override public void onMessageReceived(@NonNull RemoteMessage m){super.onMessageReceived(m);PushNotificationsPlugin.sendRemoteMessage(m);showDeliveryAlert(m);}@Override public void onNewToken(@NonNull String t){super.onNewToken(t);PushNotificationsPlugin.onNewToken(t);}private void showDeliveryAlert(RemoteMessage m){String title=value(m,"title","New delivery order"),pickup=value(m,"pickup","Food shop"),drop=value(m,"drop","Customer address"),earning=value(m,"earning","0"),orderId=value(m,"orderId","");createChannel();Intent popup=new Intent(this,DeliveryAlertActivity.class).putExtra("title",title).putExtra("pickup",pickup).putExtra("drop",drop).putExtra("earning",earning).putExtra("orderId",orderId).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent fs=PendingIntent.getActivity(this,orderId.hashCode(),popup,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Intent open=new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP).putExtra("orderId",orderId);PendingIntent app=PendingIntent.getActivity(this,orderId.hashCode()+1,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);NotificationCompat.Builder n=new NotificationCompat.Builder(this,CHANNEL_ID).setSmallIcon(getApplicationInfo().icon).setContentTitle(title).setContentText(pickup+" -> "+drop).setStyle(new NotificationCompat.BigTextStyle().bigText("Pickup: "+pickup+"\nDrop: "+drop+"\nDelivery earning: Rs "+earning)).setPriority(NotificationCompat.PRIORITY_MAX).setCategory(NotificationCompat.CATEGORY_MESSAGE).setAutoCancel(true).setContentIntent(app).setFullScreenIntent(fs,true).setVibrate(new long[]{0,300,140,350}).setDefaults(NotificationCompat.DEFAULT_SOUND);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(orderId.hashCode(),n.build());}private void createChannel(){if(Build.VERSION.SDK_INT<Build.VERSION_CODES.O)return;NotificationChannel c=new NotificationChannel(CHANNEL_ID,"Urgent delivery popup alerts",NotificationManager.IMPORTANCE_HIGH);c.setDescription("Full-screen new delivery alerts with accept and decline buttons");c.enableVibration(true);c.setVibrationPattern(new long[]{0,300,140,350});((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);}private String value(RemoteMessage m,String key,String fallback){String v=m.getData().get(key);return v==null||v.trim().isEmpty()?fallback:v;}}